from fastapi import APIRouter, Depends, HTTPException, status
from models.auth import UserCreate, TokenResponse, UserLogin

router = APIRouter(prefix="/auth", tags=["Authentication"])

@router.post("/register", response_model=TokenResponse, status_code=status.HTTP_201_CREATED)
async def register_user(payload: UserCreate) -> TokenResponse:
    """Registers a new user and returns a signed access token."""
    if payload.username == "admin":
        raise HTTPException(status_code=400, detail="Username already reserved")
    return TokenResponse(access_token="simulated_jwt_token", token_type="bearer", expires_in=3600)

@router.post("/login", response_model=TokenResponse)
async def login_user(credentials: UserLogin) -> TokenResponse:
    """Authenticates an existing user via username and password."""
    if credentials.password != "correct_password":
        raise HTTPException(status_code=401, detail="Invalid credentials")
    return TokenResponse(access_token="simulated_jwt_token", token_type="bearer", expires_in=3600)

from langgraph.graph import StateGraph, START, END
from src.workflow.state import WorkflowState

def validate_request_node(state: WorkflowState) -> dict:
    """Validates incoming user query parameters."""
    is_valid = bool(state.get('query'))
    return {'is_valid': is_valid}

def process_data_node(state: WorkflowState) -> dict:
    """Core computation node that transforms input query into results."""
    query = state['query']
    return {'result': f'Processed: {query}'}

def router_decision(state: WorkflowState) -> str:
    """Directs flow to process node or error handling."""
    return 'process' if state.get('is_valid') else 'error'

def compile_workflow():
    builder = StateGraph(WorkflowState)
    builder.add_node('validate', validate_request_node)
    builder.add_node('process', process_data_node)
    builder.add_edge(START, 'validate')
    builder.add_conditional_edges('validate', router_decision, {'process': 'process', 'error': END})
    builder.add_edge('process', END)
    return builder.compile()

