from langgraph.graph import StateGraph, START, END
from src.supervisor.state import SupervisorState

def route_user_request(state: SupervisorState) -> str:
    """Evaluates user intent and returns appropriate subagent identifier."""
    intent = state.get('primary_intent', 'qa')
    mapping = {'docgen': 'docgen_subgraph', 'qa': 'qa_subgraph', 'srs': 'srs_subgraph'}
    return mapping.get(intent, 'qa_subgraph')

def build_supervisor_graph():
    workflow = StateGraph(SupervisorState)
    workflow.add_node('router', lambda s: {'status': 'routed'})
    workflow.add_conditional_edges('router', route_user_request, {
        'docgen_subgraph': END,
        'qa_subgraph': END,
        'srs_subgraph': END
    })
    workflow.add_edge(START, 'router')
    return workflow.compile()

