from fastapi import APIRouter, Request, HTTPException, Header
import stripe

router = APIRouter(prefix="/webhooks", tags=["Billing"])

@router.post("/stripe")
async def stripe_webhook(request: Request, stripe_signature: str = Header(None)):
    """Handles inbound Stripe webhook events with HMAC signature validation."""
    payload = await request.body()
    try:
        event = stripe.Webhook.construct_event(payload, stripe_signature, endpoint_secret="whsec_test_secret")
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid payload payload")
    except stripe.error.SignatureVerificationError:
        raise HTTPException(status_code=400, detail="Invalid Stripe signature")

    if event["type"] == "invoice.paid":
        return {"status": "success", "event": "invoice.paid"}
    return {"status": "ignored"}

import ast
from typing import List, Dict

class ASTSymbolExtractor:
    """Extracts function signatures, class declarations, and docstrings using Python AST."""
    def extract_symbols(self, code: str) -> List[Dict[str, str]]:
        tree = ast.parse(code)
        symbols = []
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                symbols.append({'type': 'function', 'name': node.name, 'lineno': node.lineno})
            elif isinstance(node, ast.ClassDef):
                symbols.append({'type': 'class', 'name': node.name, 'lineno': node.lineno})
        return symbols

