from typing import List, Dict

def reciprocal_rank_fusion(dense_ranks: List[str], sparse_ranks: List[str], k: int = 60) -> List[Dict[str, float]]:
    """Computes RRF score: RRF(d) = sum(1 / (k + rank(d)))"""
    scores = {}
    for rank, doc_id in enumerate(dense_ranks, start=1):
        scores[doc_id] = scores.get(doc_id, 0.0) + (1.0 / (k + rank))
    for rank, doc_id in enumerate(sparse_ranks, start=1):
        scores[doc_id] = scores.get(doc_id, 0.0) + (1.0 / (k + rank))
    sorted_docs = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    return [{'doc_id': doc, 'rrf_score': score} for doc, score in sorted_docs]

from typing import Dict, Set
from fastapi import WebSocket

class WebSocketConnectionManager:
    """Maintains active client WebSocket sessions and provides broadcast capabilities."""
    def __init__(self):
        self.active_connections: Dict[str, Set[WebSocket]] = {}

    async def connect(self, room_id: str, websocket: WebSocket) -> None:
        """Accepts client connection and subscribes to specified room."""
        await websocket.accept()
        if room_id not in self.active_connections:
            self.active_connections[room_id] = set()
        self.active_connections[room_id].add(websocket)

    def disconnect(self, room_id: str, websocket: WebSocket) -> None:
        """Removes client from active room pool."""
        if room_id in self.active_connections:
            self.active_connections[room_id].discard(websocket)

    async def broadcast_json(self, room_id: str, message: dict) -> int:
        """Broadcasts JSON message payload to all subscribers in room. Returns recipient count."""
        connections = self.active_connections.get(room_id, set())
        for conn in list(connections):
            await conn.send_json(message)
        return len(connections)

class ChannelSubscriptionHub:
    """Handles room access permissions and channel quota governance."""
    def __init__(self, max_subscribers_per_room: int = 1000):
        self.max_subscribers = max_subscribers_per_room

    def can_join(self, current_count: int) -> bool:
        return current_count < self.max_subscribers

